with memberships(subscription_id, old_name, new_name) as (values
    ('00000000-0000-4000-8000-000000000050'::uuid, 'Campus Video', 'Tencent Video VIP'),
    ('00000000-0000-4000-8000-000000000051'::uuid, 'Campus Music', 'QQ Music Green Diamond'),
    ('00000000-0000-4000-8000-000000000052'::uuid, 'Campus Cloud', 'Baidu Netdisk SVIP'),
    ('00000000-0000-4000-8000-000000000053'::uuid, 'Campus Study', 'Taobao 88VIP')
)
